// Produce and verify one prologue step from one entry: "add" for a new step, "refresh" after an entry was corrected.
// args from node tools/args.cjs <topic> beat add|refresh <id> "<context>" ["<extra rules>"].
// After: node tools/add-beat.cjs <topic> <output> <section-key> ["<gap note>"]  or  node tools/refresh-beat.cjs <topic> <output> [--match "<regex>"] ["<what changed>"]
export const meta = {
  name: 'count-prologue-beat',
  description: 'Produce one prologue step for The Count from one tracker entry or ledger item (a finder reads only that record, a verifier checks every fact, source, quote and speaker against it)',
  phases: [{ title: 'Beat', detail: 'finder then verifier, Sonnet', model: 'sonnet' }],
}
const A = args
if (!A || !A.id || !A.mode || !A.context) throw new Error('args missing; generate them with node tools/args.cjs <topic> beat add|refresh <id> "<context>"')
const isLedger = A.id.startsWith('ledger:')
const SOURCE = isLedger ? `the ledger item in ${A.ledgerJson} (array "items": the item whose "date" is ${A.id.slice(7, 17)} and whose "title" starts with ${JSON.stringify(A.id.slice(18))}; read its "title", "body" and "sources") and the same bullet in ${A.ledgerMd}` : `${A.dir}${A.id}.json (fields: id, title, date, summary, keyFacts, sources[{text,url,type}], severity)`
const SRC = { type: 'object', properties: { text: { type: 'string' }, url: { type: 'string' } }, required: ['text', 'url'] }
const BEAT = { type: 'object', properties: { id: { type: 'string' }, date: { type: 'string' }, dateNote: { type: 'string' }, what: { type: 'string' }, why: { type: 'string' }, whyBasis: { type: 'string', enum: ['stated', 'inferred'] }, term: { type: 'string', enum: ['first', 'between', 'second'] }, severity: { type: 'string' }, sources: { type: 'array', items: SRC }, quote: { type: 'string' }, quoteBy: { type: 'string' }, notes: { type: 'string' } }, required: ['id', 'date', 'what', 'why', 'whyBasis', 'term', 'sources'] }
const VERDICT = { type: 'object', properties: { supported: { type: 'boolean' }, whyOk: { type: 'boolean' }, sourcesOk: { type: 'boolean' }, quoteOk: { type: 'boolean' }, dateOk: { type: 'boolean' }, issues: { type: 'string' }, fix: { type: 'string' }, quoteFix: { type: 'string' } }, required: ['supported', 'whyOk', 'sourcesOk', 'quoteOk', 'dateOk', 'issues'] }
const RULES = `Hard rules: the beat comes from this one record and nothing else. "what" is one plain sentence of at most 45 words restating what the record documents, using only facts in it and no outside knowledge. "why" (at most 30 words) ${A.whyRule}; set whyBasis "stated" only when the record says so in substance, otherwise "inferred". Copy up to three sources verbatim (text and url) from the record's sources, preferring primary documents; never type a URL from memory. "date" is the date of the event the beat describes as the record states it (YYYY-MM-DD); add a dateNote only if the date stands for something other than the event. "term" is ${A.termNote}. Include a verbatim "quote" under 25 words only when the record carries a quotation worth keeping, copied exactly, and then "quoteBy" must name who the record says said or wrote it, as the record names them; no quote without a quoteBy. No em dashes anywhere. Understate rather than overstate; the most precise language the evidence supports.${A.rules ? ' ' + A.rules : ''}`
phase('Beat')
const found = await agent(`You are ${A.mode === 'refresh' ? 'refreshing one step of' : 'adding one step to'} a sourced prologue of The Count. Context: ${A.context}.${A.mode === 'refresh' ? ' The step\'s record was corrected and the old step may now be wrong; produce the step afresh from the record as it stands.' : ''} Read ${SOURCE} in full and produce one beat for it. ${RULES} Return the beat with id ${JSON.stringify(A.id)} and a short notes field${A.mode === 'refresh' ? ' saying what the record now says that an older reading might have got wrong' : ' on what the record does not cover'}.`, { label: `find:${A.id.slice(0, 40)}`, phase: 'Beat', schema: BEAT, model: 'sonnet', effort: 'high' })
if (!found) return { error: 'finder returned nothing' }
const verdict = await agent(`You are the verifier for one prologue beat. Open ${SOURCE} and check the beat below, strictly: (1) the date is the date of the event the beat describes as the record states it (dateOk); (2) every fact in "what" appears in the record's title, summary or keyFacts (or the ledger bullet), with nothing added (supported); (3) each listed source's text and url appear verbatim in the record's sources (sourcesOk); (4) "why" is faithful to the record: if whyBasis is "stated" the record says so in substance; if "inferred" the inference is modest (whyOk); (5) any quote is verbatim and quoteBy names the speaker or document the record attributes it to, and a cut quotation does not read stronger than the full sentence (quoteOk; true when there is no quote). Default to false when uncertain. When a small rewrite of "what" would make it supported, put the rewrite in "fix" (one sentence, at most 45 words, only facts from the record); when a different quoteBy is right, put it in "quoteFix".${A.rules ? ' Extra rules the beat must meet: ' + A.rules : ''}

Beat:
${JSON.stringify(found, null, 1)}`, { label: `verify:${A.id.slice(0, 40)}`, phase: 'Beat', schema: VERDICT, model: 'sonnet', effort: 'high' })
return { beat: found, verdict }
